import test from 'node:test';
import assert from 'node:assert/strict';
import {correctProductData} from './product-title-corrections.mjs';
const rows=[{id:'6owUOP0UqtNt3y5pFzgW',titulo:'Cortina 3,00x2,80 Metros Blackout Blecaute Gelo Corta Luz Em Tecido Grosso Para Quarto E Sala Casa Laura Enxovais',listing:'MLB4008202207'},{id:'6rPnzKJkUk5676DoZ9ng',titulo:'Câmera de Segurança IP Wi-Fi Lâmpada E27 HW 360° Full HD com Visão Noturna e Áudio - HW',listing:'MLB4162108123'}];
test('triagem56 exige identidade e preserva operação e afiliados com idempotência',()=>{for(const r of rows){const p={...r,preco:'99,99',linkAfiliado:'https://meli.la/preservado',variation_id:'original'},x=correctProductData(p);for(const k of Object.keys(p).filter(k=>k!=='titulo'))assert.equal(x[k],p[k]);assert.deepEqual(correctProductData(x),x);for(const alt of [{titulo:'Capa para '+r.titulo},{id:'outro'},{link:'https://www.mercadolivre.com.br/p/MLB12345678?wid=MLB9999999999'}])assert.equal(correctProductData({...p,comentario:'preservar',...alt}).comentario,'preservar');assert.ok(x.titulo.length<=100);}});
test('cortina altera só título para exibir marca e medidas sem inventar bloqueio',()=>{const p={...rows[0],comentario:'Resumo original',pros:'Pros original',contras:'Contras original'},x=correctProductData(p);for(const k of Object.keys(p).filter(k=>k!=='titulo'))assert.equal(x[k],p[k]);assert.match(x.titulo,/Casa Laura Enxovais/);assert.match(x.titulo,/3,00 × 2,80 m/);assert.doesNotMatch(x.titulo,/100%|total|garant/i);});
test('câmera não garante 360 simultâneo, instalação ou gravação gratuita',()=>{const x=correctProductData(rows[1]);assert.equal(x.titulo,rows[1].titulo);assert.match(x.comentario,/não comprova visão simultânea/);assert.match(x.comentario,/Não presumimos cartão incluído ou gravação gratuita permanente/);assert.match(x.comentario,/não fornece instruções de ligação/);assert.doesNotMatch(x.pros,/sem pontos cegos|gratuit|facilitada|garant|cartão|contínua/i);});
test('A36 conserva a variante e o conteúdo sem edição específica',()=>{const p={id:'6tvLptYK5kpEu3H8wQXJ',titulo:'Smartphone Samsung Galaxy A36 5G 128GB 6GB RAM',comentario:'Texto original da variante 128 GB/6 GB',variation_id:'original'},x=correctProductData(p);for(const k of Object.keys(p))assert.equal(x[k],p[k]);});
